$stats = [];
$stats['pending_collection'] = $conn->query("SELECT COUNT(*) as total FROM laundry_requests WHERE status = 'Pending'")->fetch_assoc()['total'] ?? 0;
$stats['in_progress'] = $conn->query("SELECT COUNT(*) as total FROM laundry_requests WHERE status IN ('Washing', 'Drying', 'Ironing')")->fetch_assoc()['total'] ?? 0;
$stats['ready_dispatch'] = $conn->query("SELECT COUNT(*) as total FROM laundry_requests WHERE status = 'Ready'")->fetch_assoc()['total'] ?? 0;
$stats['completed'] = $conn->query("SELECT COUNT(*) as total FROM laundry_requests WHERE status IN ('Collected', 'Delivered')")->fetch_assoc()['total'] ?? 0;
$recent_activity = $conn->query("SELECT r.*, CONCAT(u.first_name, ' ', COALESCE(u.last_name, '')) as full_name FROM laundry_requests r JOIN users u ON r.user_id = u.id WHERE r.status != 'Delivered' ORDER BY r.created_at DESC LIMIT 6");
